{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Vaccines to prevent COVID-19: A living systematic review with Trial Sequential Analysis and network meta-analysis of randomized clinical trials",
      "reason": "The title explicitly identifies the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Vaccines to prevent COVID-19: A living systematic review with Trial Sequential Analysis and network meta-analysis of randomized clinical trials",
      "reason": "The title states the population/condition (COVID-19) and the intervention (vaccines to prevent COVID-19)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "A living systematic review with Trial Sequential Analysis and network meta-analysis of randomized clinical trials",
      "reason": "The title provides supplementary information: living-review status, analysis methods (Trial Sequential Analysis, network meta-analysis), and study design (randomized clinical trials)."
    }
  ],
  "confidence": 98
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Currently, there are only a few interventions hat seem able to benefit the clinical course of COVID-19 [3]. ... At September 13 th , 2021 about 104 vaccines are being tested in humans, with 33 having reached phase III trials [6]. Of these, five vaccines were abandoned due to either lack of response or an undesirable adverse event ... eight have been approved for full use, and eleven have been authorized for early or limited use [6].",
      "reason": "The introduction describes the current state of knowledge, including pandemic burden, vaccine development landscape, and current uncertainties around vaccine safety and effectiveness."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "With the rapid development, approval of vaccines for COVID-19, and the growing number of viral variants, there is a need for systematic reviews critically appraising the topic.",
      "reason": "The importance and need for the review are explicitly explained in the context of the rapidly evolving vaccine landscape."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "We recently published the first version of our review as a preprint, showing effects of mRNA and viral vector vaccines [7]. The aim of this second version of our living systematic review is to assess the effectiveness and safety of COVID-19 vaccines through analyses of all currently available randomized clinical trials.",
      "reason": "This is an update of a previous review; the prior version is identified and cited, and the rationale for the updated living review is provided."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No description of the proposed mechanism of action of COVID-19 vaccines appears in the Introduction or Background; the rationale focuses on disease burden and trial evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "The aim of this second version of our living systematic review is to assess the effectiveness and safety of COVID-19 vaccines through analyses of all currently available randomized clinical trials.",
      "reason": "The review evaluates vaccines as discrete pharmacological interventions in randomized trials, not complex multi-component interventions or delivery contexts, so a logic model is not applicable."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this second version of our living systematic review is to assess the effectiveness and safety of COVID-19 vaccines through analyses of all currently available randomized clinical trials.",
      "reason": "The Introduction explicitly states the review objective."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We included randomized clinical trials with any control group, i.e. vaccine versus placebo, 'active placebo', no intervention, another vaccine aiming at preventing COVID-19, or any other 'active' comparator [8].",
      "reason": "Population (any participants), intervention (any COVID-19 vaccine), and comparators are stated in the eligibility criteria, but the outcomes component of PICO is described separately under Methods rather than within an explicit PICO-formatted objective statement."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We searched for and included randomized clinical trials... We included trials with any participant irrespective of prior exposure, age, sex, comorbidities, immune status, and risk group. We included any vaccine aiming to prevent COVID-19 irrespective of dose and duration of administration. We included randomized clinical trials with any control group, i.e. vaccine versus placebo, 'active placebo', no intervention, another vaccine aiming at preventing COVID-19, or any other 'active' comparator",
      "reason": "Eligible study design (RCTs), population characteristics, intervention (any COVID-19 vaccine), and comparators are clearly specified, fully covering the study-design eligibility characteristics."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "irrespective of publication status, year, and language",
      "reason": "Report characteristics are explicitly addressed: no restrictions on publication status, year, or language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not distinguish exclusion because outcomes were not measured from exclusion because results were not reported; text_10 notes only that 46 trials met inclusion and 35 provided data, without explaining the basis for non-inclusion in analyses."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "All included trials assessed a COVID-19 vaccine compared with placebo (n = 32) or a control vaccine not immunogenic towards COVID-19 (n = 3). The included vaccines were based on mRNA...; viral vectors...; protein-subunit...; or inactivated virus (Table 5).",
      "reason": "Synthesis groups (vaccine platforms) and comparisons versus placebo/control vaccine are described, but mainly in the Results; the Methods do not explicitly specify and link grouping for each synthesis (e.g., how trials were grouped for each outcome's meta-analysis), relying on reference to a published protocol."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale for eligibility restrictions (e.g., restricting to randomized clinical trials only) is provided in the retrieved evidence."
    }
  ],
  "confidence": 85
}

