{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Our primary outcomes were allcause mortality; vaccine efficacy defined by either preventing COVID-19 symptoms plus positive polymerase chain rection (PCR) test, preventing severe COVID-19 symptoms plus positive PCR test, or preventing positive PCR test only; and serious adverse events [10]. Our secondary outcomes were health-related quality of life and adverse events not considered serious [8].",
      "reason": "All outcome domains (three primary, two secondary) are listed, and vaccine efficacy is explicitly defined with its component definitions."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the trial results reported at maximum follow-up for all outcomes.",
      "reason": "The time frame of measurement is specified as maximum follow-up for all outcomes, consistent with the summary of findings tables ('maximum follow-up')."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We used the trial results reported at maximum follow-up for all outcomes.",
      "reason": "The manuscript does not explicitly state whether all compatible results within each outcome domain were sought; it only indicates that a single result (maximum follow-up) was used, implying not all results were collected."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the trial results reported at maximum follow-up for all outcomes. We used intention-to-treat data if provided by the trialists [8].",
      "reason": "The selection process is described: results at maximum follow-up were used, and intention-to-treat data were preferred when available."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of changes to outcome-domain inclusion, definitions, or importance during the review; outcomes are described as predefined in the protocol."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of changes to the processes for selecting results within outcome domains is reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We assessed three primary outcomes and two secondary outcomes. We, therefore, considered a p value of 0.0167 or less as the threshold for statistical significance to adjust for multiplicity [8, 15].",
      "reason": "Primary outcomes are distinguished from secondary outcomes and prioritized in the analysis (multiplicity adjustment), but no explicit rationale for their prioritisation is provided."
    }
  ],
  "confidence": 82
}

{
