{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Association measures. Wecalculated risk ratios (RRs) with 95% confidence interval (CI).",
      "reason": "The Methods specify risk ratios with 95% CI as the effect measure, applied across outcomes (mortality, serious/non-serious adverse events), and vaccine efficacy is presented as percentages; summary of findings tables consistently report relative effects (RR or efficacy %) for each outcome."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We, therefore, considered a p value of 0.0167 or less as the threshold for statistical significance to adjust for multiplicity [8, 15].",
      "reason": "A statistical significance threshold (p=0.0167) and TSA-based DARIS assumptions (e.g., RRR 20%/50% in tables) are reported, but explicit thresholds/ranges for interpreting the magnitude of effect sizes and their rationale are not fully described."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Results are re-expressed as illustrative comparative risks (assumed/corresponding risk per 10,000) in summary of findings tables, but no Methods text describes how such re-expression of synthesized results was performed."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript states that risk ratios were calculated but provides no justification or rationale for choosing this effect measure."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "46 trials met our inclusion criteria [34-65], of which 35 trials [34, 36-42, 44-50, 53-59, 61-65] randomizing 219 864 participants provided data for our predefined meta-analyses... The included vaccines were based on mRNA [34, 41, 42, 66]; viral vectors [37, 39, 43, 45, 47, 50, 52, 67]; protein-subunit [38, 53]; or inactivated virus [47-49, 51] (Table 5).",
      "reason": "The manuscript indicates which trials provided data for the predefined meta-analyses and tabulates included trials by vaccine type (Table 5), implying grouping for syntheses. However, an explicit description of the process used to decide which studies were eligible for each synthesis (e.g., comparing intervention characteristics against planned groups) is not fully described; eligibility criteria (text_8) cover study inclusion generally, not per-synthesis decisions."
    }
  ],
  "confidence": 70
}

